import { API_BASE_URL } from '../config/api';

export interface HourlyPoint {
  time: string;
  tempC: number;
  condition: string;
}

export interface DaySummary {
  day: string;
  highC: number;
  lowC: number;
  condition: string;
}

export interface Weather {
  current: { tempC: number; condition: string; feelsLikeC: number };
  hourly: HourlyPoint[];
  days: DaySummary[];
}

export async function fetchWeather(): Promise<Weather> {
  const response = await fetch(`${API_BASE_URL}/weather/forecast`);
  if (!response.ok) throw new Error(`Weather failed with status ${response.status}`);
  return (await response.json()) as Weather;
}

import { useCallback, useEffect, useState } from 'react';
import { View, Text, TouchableOpacity, FlatList, StyleSheet, SafeAreaView, ActivityIndicator, RefreshControl } from 'react-native';
import { fetchWeather, type Weather, type HourlyPoint } from '../services/weather';

const colors = {
  accent: '#f05039',
  bg: '#0f120e',
  danger: '#ff6b5e',
  text: '#f5f5f0',
  textMuted: '#a8ada6',
  muted: '#8a8f8a',
  textSoft: '#d8dbd4',
  border: '#242a24',
}

const CONDITION_ICON: Record<string, string> = { sunny: '☀️', cloudy: '☁️', rain: '🌧', snow: '❄️' };
const iconFor = (condition: string): string => CONDITION_ICON[condition.toLowerCase()] ?? '☁️';

export function WeatherScreen(): JSX.Element {
  const [weather, setWeather] = useState<Weather | null>(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [selected, setSelected] = useState<HourlyPoint | null>(null);

  const load = useCallback(async () => {
    try {
      const data = await fetchWeather();
      setWeather(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load weather.');
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, []);

  useEffect(() => { void load(); }, [load]);

  const temps = weather ? weather.hourly.map(h => h.tempC) : [];
  const min = Math.min(...temps, 0);
  const max = Math.max(...temps, 1);
  const curveY = (tempC: number): number => ((tempC - min) / (max - min || 1)) * 90;

  const renderDay = useCallback(({ item }: { item: { day: string; highC: number; lowC: number; condition: string } }) => (
    <View style={styles.dayRow} accessibilityLabel={`${item.day}: high ${item.highC}, low ${item.lowC}`}>
      <Text style={styles.dayName}>{item.day}</Text>
      <Text style={styles.dayIcon}>{iconFor(item.condition)}</Text>
      <Text style={styles.dayLow}>{item.lowC}°</Text>
      <View style={styles.dayBar}>
        <View style={[styles.dayBarFill, { left: `${(item.lowC - min) / (max - min || 1) * 100}%`, right: `${100 - ((item.highC - min) / (max - min || 1)) * 100}%` }]} />
      </View>
      <Text style={styles.dayHigh}>{item.highC}°</Text>
    </View>
  ), [min, max]);

  const current = selected ?? (weather?.hourly[0] ?? null);

  return (
    <SafeAreaView style={styles.safe}>
      {loading && <ActivityIndicator color="{colors.accent}" style={styles.center} />}
      {!loading && error && <Text style={styles.error}>{error}</Text>}
      {!loading && weather && (
        <FlatList
          data={weather.days.map(d => ({ ...d, key: d.day }))}
          renderItem={renderDay}
          keyExtractor={d => d.key}
          refreshControl={<RefreshControl refreshing={refreshing} onRefresh={() => { setRefreshing(true); void load(); }} tintColor="{colors.accent}" />}
          ListHeaderComponent={
            <View>
              <View style={styles.current}>
                <Text style={styles.currentIcon}>{iconFor(weather.current.condition)}</Text>
                <Text style={styles.currentTemp}>{current?.tempC ?? weather.current.tempC}°</Text>
                <Text style={styles.currentCond}>{current?.condition ?? weather.current.condition}</Text>
                <Text style={styles.feels}>feels like {weather.current.feelsLikeC}°</Text>
              </View>
              <Text style={styles.section}>Hourly</Text>
              <View style={styles.curve} accessibilityLabel="Hourly temperature curve">
                {weather.hourly.map((point, i) => (
                  <TouchableOpacity
                    key={i}
                    style={[styles.point, { top: 96 - curveY(point.tempC), left: `${(i / (weather.hourly.length - 1)) * 100}%` }]}
                    onPress={() => setSelected(point)}
                    accessibilityRole="button"
                    accessibilityLabel={`${new Date(point.time).toLocaleTimeString([], { hour: '2-digit' })} ${point.tempC} degrees`}
                  />
                ))}
              </View>
              <Text style={styles.section}>5-day forecast</Text>
            </View>
          }
        />
      )}
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: colors.bg },
  center: { marginTop: 40 },
  error: { color: colors.danger, textAlign: 'center', marginTop: 24 },
  current: { alignItems: 'center', paddingVertical: 20 },
  currentIcon: { fontSize: 56 },
  currentTemp: { color: colors.text, fontSize: 56, fontWeight: '800', marginTop: 4 },
  currentCond: { color: colors.textMuted, fontSize: 16 },
  feels: { color: colors.muted, fontSize: 12, marginTop: 4 },
  section: { color: colors.textSoft, fontWeight: '700', paddingHorizontal: 16, paddingBottom: 8 },
  curve: { height: 110, marginHorizontal: 16, marginBottom: 16, position: 'relative', borderBottomWidth: 1, borderBottomColor: colors.border },
  point: { position: 'absolute', width: 10, height: 10, borderRadius: 5, backgroundColor: colors.accent, transform: [{ translateX: -5 }, { translateY: -5 }] },
  dayRow: { flexDirection: 'row', alignItems: 'center', gap: 10, paddingHorizontal: 16, paddingVertical: 10 },
  dayName: { color: colors.text, width: 52 },
  dayIcon: { width: 24, textAlign: 'center' },
  dayLow: { color: colors.muted, width: 34, textAlign: 'right' },
  dayBar: { flex: 1, height: 6, borderRadius: 3, backgroundColor: colors.border, position: 'relative' },
  dayBarFill: { position: 'absolute', top: 0, bottom: 0, backgroundColor: colors.accent, borderRadius: 3 },
  dayHigh: { color: colors.text, width: 34, textAlign: 'right' },
});
